// Independent necessary boundary test. Literature four-loop targets are read
// only here, and every output remains under holdouts; no sewing input is written.
#include "boundary_tensor_train.hpp"
using namespace boundary_tt;
static double elapsed(std::chrono::steady_clock::time_point s){return std::chrono::duration<double>(std::chrono::steady_clock::now()-s).count();}
static Mat difference(Mat a,const Mat& b){require(a.nrow==b.nrow&&a.ncol==b.ncol,"difference shape");for(size_t i=0;i<a.nrow;++i){for(auto[j,x]:b[i])a[i].push_back(j,-x);normalize(a[i]);}return a;}
int main(int argc,char**argv){try{
 require(argc==3,"usage boundary_holdout_probe EXPERIMENT DC|TC");fs::path exp=argv[1];std::string name=argv[2];require(name=="DC"||name=="TC","boundary name");fs::path input=exp/"boundary"/name,out=exp/"holdouts"/(name+"_prefix_probe");fresh(out);fs::create_directories(out/"auxiliary");rref_option_t opt;opt->pool.reset(1);auto start=std::chrono::steady_clock::now();
 auto h8=load(input/"train/H8"),r4=load(exp/"holdouts"/(name+"_train")/"R4");require(h8.q==r4.q&&h8.core.size()==8&&r4.core.size()==8,"normalized target train shapes");size_t q=h8.q;auto target=sum({{h8,Q(1)},{r4,Q(1)}} ,opt);compress(target,opt);
 // Check the normalized sum after every exact compression (factor() itself
 // verifies every coefficient of every matrix factorization).
 uint64_t rng=927461;size_t nonzero=0;for(size_t test=0;test<200;++test){Word word(8);for(auto&x:word){rng=rng*6364136223846793005ULL+1442695040888963407ULL;x=(rng>>32)%(test<100?(name=="DC"?6:9):q);}auto expected=coefficient(h8,word)+coefficient(r4,word);require(coefficient(target,word)==expected,"independent H8+R4 coefficient control");if(expected!=0)++nonzero;}h8=Train{};r4=Train{};save(out/"F4_target_train",target);std::cout<<"TARGET_READY ranks=";for(auto r:target.rank)std::cout<<r<<',';std::cout<<" sampled_nonzero="<<nonzero<<" seconds="<<elapsed(start)<<std::endl;
 auto c=target.core[0];Mat u(target.rank[1],q);for(auto[j,x]:c[0])u[j%target.rank[1]].push_back(index(j/target.rank[1]),x);for(auto&row:u.rows)normalize(row);
 auto [p1coeff,p1]=factor(read_matrix(input/"collinear/first_w1.wxf"),opt);Chart first_chart(p1,opt);auto first_coeff=first_chart.coordinates(u,false);auto first_residual=difference(u,mul(first_coeff,p1));bool first_pass=!first_residual.nnz();write(out/"prefix_w1_residual.wxf",first_residual);
 size_t old=q,lastnp=0;std::vector<size_t>extra_counts;std::ofstream progress(out/"prefix_progress.jsonl");
 for(size_t k=2;k<=6;++k){
  auto t=read(input/"collinear"/("first_w"+std::to_string(k)+"_basis.wxf"));require(t.dim(2)==q&&t.dim(1)<=old,"candidate boundary recurrence");size_t np=t.dim(0),prev=t.dim(1);Mat b=flatten(t);t.clear();b.ncol=old*q;
  std::vector<unsigned char>count(prev*q,0);for(auto&row:b.rows)for(auto[j,x]:row)if(count[j]<2)++count[j];std::vector<I>piv(np,-1),col(old*q,-1);std::vector<Q>scale(np);
  for(size_t i=0;i<np;++i)for(auto[j,x]:b[i])if(count[j]==1){piv[i]=j;scale[i]=x;col[j]=index(i);break;}require(std::all_of(piv.begin(),piv.end(),[](I i){return i>=0;}),"candidate complete private chart");
  c=target.core[k-1];require(c.nrow==u.nrow&&c.ncol==q*target.rank[k],"target train recurrence");Mat next(target.rank[k],old*q);
  for(size_t a=0;a<c.nrow;++a)for(auto[z,x]:c[a]){size_t l=z/target.rank[k],s=z%target.rank[k];for(auto[j,y]:u[a])next[s].push_back(index(size_t(j)*q+l),x*y);}for(auto&row:next.rows)normalize(row);
  Mat coeff(next.nrow,np);for(size_t s=0;s<next.nrow;++s)for(auto[j,x]:next[s])if(col[j]>=0)coeff[s].push_back(col[j],x/scale[col[j]]);for(auto&row:coeff.rows)normalize(row);
  auto residual=difference(std::move(next),mul(coeff,b));b.clear();auto [extra_coeff,extra_basis]=factor(residual,opt);size_t ne=extra_basis.nrow;extra_counts.push_back(ne);
  write_tensor_view(out/"auxiliary"/("prefix_residual_w"+std::to_string(k)+".wxf"),MatrixTensorView(residual,{residual.nrow,old,q}));residual.clear();write_tensor_view(out/"auxiliary"/("extra_basis_w"+std::to_string(k)+".wxf"),MatrixTensorView(extra_basis,{ne,old,q}));extra_basis.clear();
  u=Mat(target.rank[k],np+ne);for(size_t s=0;s<u.nrow;++s){u[s]=std::move(coeff[s]);for(auto[j,x]:extra_coeff[s])u[s].push_back(index(np+j),x);normalize(u[s]);}write(out/("target_prefix_w"+std::to_string(k)+".wxf"),u);
  progress<<"{\"weight\":"<<k<<",\"candidate_dimension\":"<<np<<",\"additional_target_prefix_directions\":"<<ne<<",\"target_bond_dimension\":"<<target.rank[k]<<",\"all_factorization_residuals_zero\":true,\"seconds\":"<<elapsed(start)<<"}\n";progress.flush();std::cout<<"PREFIX weight="<<k<<" candidate="<<np<<" extra="<<ne<<" seconds="<<elapsed(start)<<std::endl;old=np+ne;lastnp=np;
 }
 auto& c7=target.core[6];auto& c8=target.core[7];Mat tail(target.rank[6],q*q);for(size_t a=0;a<tail.nrow;++a){for(auto[j,x]:c7[a])for(auto[l,y]:c8[j%target.rank[7]])tail[a].push_back(index((j/target.rank[7])*q+l),x*y);normalize(tail[a]);}
 auto h=mul(transpose(u),tail);write_tensor_view(out/"F4_target_joint6_raw2.wxf",MatrixTensorView(h,{old,q,q}));Mat extra_h(old-lastnp,q*q);for(size_t i=lastnp;i<old;++i)extra_h[i-lastnp]=h[i];write(out/"prefix6_actual_target_obstruction.wxf",extra_h);bool prefix_pass=first_pass&&!extra_h.nnz();
 // The actual reachable two-letter suffix is contracted before deciding
 // prefix membership, so unused bond-state artifacts cannot give a false fail.
 auto physical_suffix=read_matrix(input/"suffix_TF175_raw2.wxf");auto [suffix_coeff,suffix_basis]=factor(physical_suffix,opt);Chart suffix_chart(suffix_basis,opt);auto hc=suffix_chart.coordinates(h,false);auto suffix_residual=difference(h,mul(hc,suffix_basis));bool suffix_pass=!suffix_residual.nnz();write(out/"suffix_actual_target_obstruction.wxf",suffix_residual);write(out/"projected_suffix_row_basis.wxf",suffix_basis);write(out/"target_suffix_basis_coordinates.wxf",hc);
 if(prefix_pass){h.rows.resize(lastnp);h.nrow=lastnp;write_tensor_view(out/"F4_target_prefix6_raw2.wxf",MatrixTensorView(h,{lastnp,q,q}));}
 std::ofstream receipt(out/"receipt.json");receipt<<"{\"boundary\":\""<<name<<"\",\"necessary_boundary_test_pass\":"<<(prefix_pass&&suffix_pass?"true":"false")<<",\"first_entry_prefix_test_pass\":"<<(first_pass?"true":"false")<<",\"prefix6_membership\":"<<(prefix_pass?"true":"false")<<",\"suffix_TF175_image_membership\":"<<(suffix_pass?"true":"false")<<",\"candidate_prefix_dimension\":"<<lastnp<<",\"target_joint_prefix_dimension\":"<<old<<",\"projected_suffix_dimension\":"<<suffix_basis.nrow<<",\"prefix_obstruction_nonzeros\":"<<extra_h.nnz()<<",\"suffix_obstruction_nonzeros\":"<<suffix_residual.nnz()<<",\"target_nonzeros\":"<<h.nnz()<<",\"all_exact_train_factorizations_pass\":true,\"normalized_sum_coefficient_controls\":200,\"normalized_sum_nonzero_controls\":"<<nonzero<<",\"full_H8_including_finite_R2_squared\":true,\"published_R4_used_only_as_holdout\":true,\"global_candidate_coefficients_read\":false,\"parent_sewing_inputs_written\":false,\"scope\":\"Necessary independent four-loop boundary membership only, not global sewing or existence.\",\"seconds\":"<<elapsed(start)<<"}\n";
 std::cout<<"HOLDOUT_COMPLETE prefix="<<prefix_pass<<" suffix="<<suffix_pass<<" prefix_obstruction_nnz="<<extra_h.nnz()<<" suffix_obstruction_nnz="<<suffix_residual.nnz()<<" seconds="<<elapsed(start)<<std::endl;
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
